        List<String> lines = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) lines.add(line);
        int pos = 0;
        int stonesLen = Integer.parseInt(lines.get(pos++).trim());
        int[] stones = new int[stonesLen];
        if (stonesLen > 0) {
